def fetch_database_file(path: str, db_name: str, cached: int=0, ecosystem:
    Optional[Ecosystem]=None) ->Dict[str, Any]:
    file_path = os.path.join(path, db_name)
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
        return data
    except FileNotFoundError:
        raise DatabaseFileNotFoundError(filedir=path, filename=db_name)
    except json.JSONDecodeError as e:
        raise MalformedDatabase(reason=e, fetched_from=file_path)
